\label{def:sub}
The Frech\'et subdifferential $\hat\partial h$ of $h$ at $\mathbf{x}\in\mathop{\mathrm{dom}} h$ is the set of $\mathbf{u}$ such that
\begin{align}
\liminf_{\mathbf{z}\neq\mathbf{x}, \mathbf{z}\to\mathbf{x}} \frac{h(\mathbf{z}) - h(\mathbf{x}) - \mathbf{u}^\top(\mathbf{z}-\mathbf{x})}{\|\mathbf{z}-\mathbf{x}\|} \geq 0,
\end{align}
while the (limiting) subdifferential $\partial h$ at $\mathbf{x}\in\mathop{\mathrm{dom}} h$ is the ``closure'' of $\hat\partial h$:
\begin{align}
\{ \mathbf{u}: \exists \mathbf{x}^k \to \mathbf{x}, h(\mathbf{x}^k) \to h(\mathbf{x}), \mathbf{u}^k \in \hat{\partial} h(\mathbf{x}^k), \mathbf{u}^k \to \mathbf{u} \}.
\end{align}
The critical points of $h$ are $\mathop{\mathrm{crit}} h := \{ \mathbf{x}: \mathbf{0}\in\partial h(\mathbf{x}) \}$.

\begin{align}
\liminf_{\mathbf{z}\neq\mathbf{x}, \mathbf{z}\to\mathbf{x}} \frac{h(\mathbf{z}) - h(\mathbf{x}) - \mathbf{u}^\top(\mathbf{z}-\mathbf{x})}{\|\mathbf{z}-\mathbf{x}\|} \geq 0,
\end{align}

\begin{align}
\{ \mathbf{u}: \exists \mathbf{x}^k \to \mathbf{x}, h(\mathbf{x}^k) \to h(\mathbf{x}), \mathbf{u}^k \in \hat{\partial} h(\mathbf{x}^k), \mathbf{u}^k \to \mathbf{u} \}.
\end{align}

\label{def: distance}
The distance function {w.r.t.}\xspace a closed set $\Omega \subseteq \mathds{R}^d$ is defined as:
\begin{align}

\mathrm{dist}_{\Omega}(\mathbf{x}) := \min_{\mathbf{y}\in\Omega} \|\mathbf{y}-\mathbf{x}\|,  
\end{align}
while the metric projection onto $\Omega$ is defined  as:
\begin{align}
\proj{\Omega}(\mathbf{x}) := \mathop{\mathrm{argmin}}_{\mathbf{y}\in\Omega} \|\mathbf{y}-\mathbf{x}\|,
\end{align}
where $\|\cdot\|$ is the usual Euclidean norm.

