\label{def:prox_map}
The proximal map of a closed and proper function $h$ is (with parameter $\eta > 0$):
\begin{align}

\prox{h}(\mathbf{x}) := \mathop{\mathrm{argmin}}_{\mathbf{z}\in \mathds{R}^d} h(\mathbf{z}) + \tfrac{1}{2\eta}\|\mathbf{z} - \mathbf{x}\|^2.
\end{align}
Occasionally, we will write $\prox[]{h}$ instead of $\prox[1]{h}$.

\begin{align}

\prox{h}(\mathbf{x}) := \mathop{\mathrm{argmin}}_{\mathbf{z}\in \mathds{R}^d} h(\mathbf{z}) + \tfrac{1}{2\eta}\|\mathbf{z} - \mathbf{x}\|^2.
\end{align}

\begin{align}
\label{eq:ne}
\forall \mathbf{x}, \forall \mathbf{y}, ~ \|\prox{h}(\mathbf{x}) - \prox{h}(\mathbf{y}) \| \leq \|\mathbf{x} - \mathbf{y}\|,
\end{align}

\begin{align}
