\label{assum:smooth}
The gradient $\nabla f$ of $f$ is $L$-Lipschitz continuous:
\begin{align}
\forall \mathbf{x}, \forall \mathbf{y}, ~ \| \nabla f(\mathbf{x}) - \nabla f(\mathbf{y}) \| \leq L \|\mathbf{x} - \mathbf{y}\|.
\end{align}

\begin{align}
	\forall \mathbf{x}, \forall \mathbf{y}, ~ \| \nabla f(\mathbf{x}) - \nabla f(\mathbf{y}) \| \leq L \|\mathbf{x} - \mathbf{y}\|.
	\end{align}

\begin{align}
\label{eq:qb}
\forall \mathbf{x}, \forall \mathbf{y}, ~f(\mathbf{x}) \leq f(\mathbf{y}) + \langle \mathbf{x} - \mathbf{y}, \nabla f(\mathbf{y}) \rangle + \tfrac{L}{2} \|\mathbf{x} - \mathbf{y}\|^2.
\end{align}

