	It is clear from \Cref{thm:limitcon} that $\{\mathbf{x}(t)\}$ and $\{\mathbf{x}^i(t)\}, i=1, \ldots, p$, share the same set of limit points, and we need to show that any limit point of $\{\mathbf{x}(t)\}$ is also a critical point of $F$.

	Let $\mathbf{x}^*$ be a limit point of $\{\mathbf{x}(t)\}$. By \Cref{def:sub} it suffices to exhibit a sequence $\mathbf{x}(k)$ satisfying\footnote{Technically, from \Cref{def:sub} we should have the Frech\'et subdifferential $\hat{\partial} F$ in \cref{crit_want}, however, a standard argument allows us to use the more convenient subdifferential \cite[Proposition 8.7]{vari_ana}.} 
	\begin{align}\label{crit_want}
	\mathbf{x}(k) \to \mathbf{x}^*, ~ F(\mathbf{x}(k)) \to F(\mathbf{x}^*), ~ \mathbf{0} \leftarrow \mathbf{u}(k) \in \partial F(\mathbf{x}(k)).
	\end{align} 

	Let us first construct the subgradient sequence $\mathbf{u}(k)$. Consider machine $i$ and any $\hat t \in T_i$, the optimality condition of \cref{update_exp} gives
	\begin{flalign}
	u_i( \hat t+1) := -\tfrac{1}{\eta} \left[x_i(\hat t+1) - x_i(\hat t) + \eta \nabla_{i} f\big(\mathbf{x}^i(\hat t)\big)\right] \in \partial g_i(x_i( \hat t+1)).
	\end{flalign}
	It then follows that 
	\begin{flalign}
	\|u_i( \hat t+1) & + \nabla_i f(\mathbf{x}( \hat t+1))\| \nonumber\\
	&\leq 
	\|u_i( \hat t+1) + \nabla_i f(\mathbf{x}( \hat t ))\| + \|\nabla_i f(\mathbf{x}( \hat t+1)) - \nabla_i f(\mathbf{x}(\hat t))\|
	\nonumber\\
	&\overset{\mathrm{(i)}}{\le} 
	\left\| \tfrac{1}{\eta} \left[ x_i( \hat t+1) - x_i(\hat t) \right] + \nabla_{i} f\big(\mathbf{x}^{i}(\hat t)\big) - \nabla_{i} f\big(\mathbf{x}(\hat t)\big) \right\| + L\|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	&\overset{\mathrm{(ii)}}{\le} 
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \|\mathbf{x}^{i}(\hat t) - \mathbf{x}(\hat t)\| + L \|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	\label{sub_zero_1}
	&\overset{\mathrm{(iii)}}{\le}
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \sum_{k=(\hat t-s)_+}^{\hat t} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|,
	\end{flalign}
	where (i) and (ii) are due to the $L$-Lipschitz continuity of $\nabla f$, and (iii) follows from \cref{incon_bound}.
